:root { --black: #111318; --black-2: #191c23; --blue: #2457d6; --blue-dark: #1d46ad; --bg: #f4f6f9; --surface: #fff; --text: #171a21; --muted: #667085; --border: #e2e6ec; --soft: #eef2f8; --danger: #b42318; --warning: #9a6700; --success: #147a45; --radius: 10px; --shadow: 0 1px 2px rgba(16,24,40,.04),0 8px 24px rgba(16,24,40,.04); }* { box-sizing: border-box; }html, body { margin: 0px; min-height: 100%; font-family: Inter, Arial, sans-serif; color: var(--text); background: var(--bg); }button, input, select { font: inherit; }.sidebar { position: fixed; inset: 0px auto 0px 0px; width: 248px; background: var(--black); color: rgb(255, 255, 255); display: flex; flex-direction: column; z-index: 20; }.brand { padding: 28px 26px 24px; border-bottom: 1px solid rgba(255, 255, 255, 0.09); }.brand-name { font-size: 22px; font-weight: 700; letter-spacing: -0.5px; }.brand-name::after { content: ""; display: inline-block; width: 26px; height: 3px; background: var(--blue); margin-left: 8px; vertical-align: middle; }.brand-subtitle { margin-top: 5px; font-size: 12px; color: rgb(174, 182, 197); letter-spacing: 0.08em; text-transform: uppercase; }.nav { padding: 16px 12px; overflow: auto; flex: 1 1 0%; }.nav-item { width: 100%; border: 0px; background: transparent; color: rgb(201, 207, 218); text-align: left; padding: 10px 14px; border-radius: 7px; cursor: pointer; font-size: 13px; margin: 1px 0px; }.nav-item:hover { background: rgba(255, 255, 255, 0.06); color: rgb(255, 255, 255); }.nav-item.active { background: var(--blue); color: rgb(255, 255, 255); font-weight: 600; }.nav-label { padding: 20px 14px 7px; color: rgb(129, 138, 155); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; }.sidebar-footer { padding: 18px 24px; border-top: 1px solid rgba(255, 255, 255, 0.09); }.sidebar-user { font-size: 13px; font-weight: 600; }.sidebar-role { font-size: 11px; color: rgb(159, 168, 184); margin-top: 4px; }.logout-btn { border: 0px; padding: 0px; background: none; color: rgb(174, 182, 197); font-size: 12px; margin-top: 15px; cursor: pointer; }.logout-btn:hover { color: rgb(255, 255, 255); }.app-shell { margin-left: 248px; min-height: 100vh; }.topbar { height: 96px; background: rgb(255, 255, 255); border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; padding: 0px 34px; position: sticky; top: 0px; z-index: 10; }.eyebrow { color: var(--blue); font-size: 11px; text-transform: uppercase; letter-spacing: 0.1em; font-weight: 700; margin-bottom: 7px; }.topbar h1 { font-size: 22px; line-height: 1.15; margin: 0px; letter-spacing: -0.4px; }.topbar-meta { display: flex; gap: 34px; text-align: right; }.topbar-meta > div { display: flex; flex-direction: column; gap: 4px; }.meta-label { font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; }.topbar-meta strong { font-size: 12px; font-weight: 600; }.status-normal { color: var(--success); }.menu-button { display: none; }.content { padding: 30px 34px 50px; max-width: 1600px; margin: auto; }.page { display: none; }.page.active { display: block; }.intro-row { display: flex; justify-content: space-between; gap: 20px; align-items: flex-start; margin-bottom: 22px; }.intro-row h2 { font-size: 20px; margin: 0px 0px 6px; }.intro-row p, .panel-heading p { margin: 0px; color: var(--muted); font-size: 13px; }.actions { display: flex; gap: 9px; }.button { border: 1px solid var(--blue); background: var(--blue); color: rgb(255, 255, 255); border-radius: 7px; padding: 9px 14px; font-size: 12px; font-weight: 600; cursor: pointer; }.button:hover { background: var(--blue-dark); }.button.secondary { background: rgb(255, 255, 255); color: var(--text); border-color: var(--border); }.button.secondary:hover { background: var(--soft); }.button.full { width: 100%; margin-top: 20px; }.text-button { border: 0px; background: none; color: var(--blue); font-size: 12px; font-weight: 600; cursor: pointer; }.metric-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 13px; margin-bottom: 18px; }.metric-grid.four { grid-template-columns: repeat(4, 1fr); }.metric-card { background: rgb(255, 255, 255); border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-left-color: ; border-left-style: ; border-left-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-top: 3px solid var(--black); border-radius: var(--radius); padding: 17px 18px; box-shadow: var(--shadow); }.metric-card:nth-child(5), .metric-card:nth-child(6) { border-top-color: var(--blue); }.metric-label { font-size: 11px; color: var(--muted); font-weight: 600; }.metric-value { font-size: 27px; font-weight: 700; margin: 10px 0px 7px; letter-spacing: -1px; }.metric-note { font-size: 10px; color: var(--muted); }.dashboard-grid { display: grid; grid-template-columns: 2fr 1fr; gap: 18px; margin-bottom: 18px; }.panel { background: rgb(255, 255, 255); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); margin-bottom: 18px; }.panel-heading { display: flex; justify-content: space-between; align-items: flex-start; gap: 15px; margin-bottom: 20px; }.panel h3, .panel-heading h3 { font-size: 14px; margin: 0px 0px 6px; }.select { border: 1px solid var(--border); background: rgb(255, 255, 255); border-radius: 6px; padding: 7px 9px; color: var(--muted); font-size: 11px; }.risk-list { display: flex; flex-direction: column; gap: 19px; }.risk-list > div { display: grid; grid-template-columns: 1fr auto; gap: 7px; font-size: 12px; }.risk-list strong { font-size: 12px; }.bar { grid-column: 1 / -1; height: 5px; background: var(--soft); border-radius: 4px; overflow: hidden; }.bar i { display: block; height: 100%; background: var(--blue); }.table-wrap { overflow: auto; }table { width: 100%; border-collapse: collapse; font-size: 12px; white-space: nowrap; }th { text-align: left; color: var(--muted); font-size: 10px; text-transform: uppercase; letter-spacing: 0.055em; font-weight: 700; padding: 0px 12px 11px; border-bottom: 1px solid var(--border); }td { padding: 13px 12px; border-bottom: 1px solid rgb(237, 240, 244); vertical-align: middle; }tbody tr:hover { background: rgb(250, 251, 252); }.badge { display: inline-block; border-radius: 999px; padding: 4px 8px; font-size: 10px; font-weight: 700; border: 1px solid; }.badge.low { color: var(--success); border-color: rgb(183, 220, 200); background: rgb(242, 250, 246); }.badge.medium { color: var(--warning); border-color: rgb(234, 213, 154); background: rgb(255, 250, 240); }.badge.high, .badge.critical { color: var(--danger); border-color: rgb(239, 183, 178); background: rgb(255, 245, 244); }.badge.pending { color: var(--blue); border-color: rgb(185, 201, 239); background: rgb(244, 247, 255); }.notice { background: rgb(247, 249, 252); border-top: 1px solid rgb(217, 224, 237); border-right: 1px solid rgb(217, 224, 237); border-bottom: 1px solid rgb(217, 224, 237); border-image: none; border-left: 3px solid var(--blue); border-radius: 7px; padding: 13px 15px; font-size: 12px; color: rgb(66, 75, 94); margin-bottom: 18px; }.countdown { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--blue); }.countdown.urgent { color: var(--danger); }.threat-layout { display: grid; grid-template-columns: 1.7fr 1fr; gap: 18px; }.detail-list { margin: 18px 0px 0px; }.detail-list > div { display: flex; justify-content: space-between; gap: 18px; padding: 11px 0px; border-bottom: 1px solid var(--border); font-size: 12px; }.detail-list dt { color: var(--muted); }.detail-list dd { margin: 0px; text-align: right; font-weight: 500; }.policy-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 18px; }.policy-card { background: rgb(255, 255, 255); border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-left-color: ; border-left-style: ; border-left-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-top: 3px solid var(--black); border-radius: var(--radius); padding: 20px; }.policy-card:nth-child(3), .policy-card:nth-child(4) { border-top-color: var(--blue); }.policy-card span { font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }.policy-card h3 { font-size: 14px; margin: 12px 0px 8px; }.policy-card p { font-size: 11px; color: var(--muted); line-height: 1.55; margin: 0px; }.empty-module { text-align: center; padding: 80px 20px; background: rgb(255, 255, 255); border: 1px solid var(--border); border-radius: var(--radius); }.empty-module h2 { font-size: 20px; margin: 0px 0px 8px; }.empty-module p { color: var(--muted); font-size: 13px; max-width: 500px; margin: 0px auto 22px; }.toast { position: fixed; right: 24px; bottom: 24px; background: var(--black); color: rgb(255, 255, 255); border-left: 4px solid var(--blue); border-radius: 7px; padding: 13px 17px; font-size: 12px; opacity: 0; transform: translateY(15px); pointer-events: none; transition: 0.2s; z-index: 50; }.toast.show { opacity: 1; transform: none; }@media (max-width: 1200px) {
