}:root { --bg: #080b12; --surface: #111620; --surface-2: #151b27; --text: #f5f7fb; --muted: #98a2b3; --border: #283142; --soft: #1b2331; --shadow: 0 10px 30px rgba(0,0,0,.22); }html, body { background: var(--bg); color: var(--text); }.topbar { background: rgb(13, 17, 25); border-color: var(--border); }.content { background: var(--bg); }.panel, .metric-card, .policy-card, .empty-module { background: var(--surface); border-color: var(--border); }.metric-card { border-top-color: rgb(59, 130, 246); }.metric-card:nth-child(5), .metric-card:nth-child(6) { border-top-color: rgb(96, 165, 250); }.button.secondary, .select { background: var(--surface-2); color: var(--text); border-color: var(--border); }.button.secondary:hover { background: rgb(32, 42, 58); }th { color: rgb(143, 155, 173); border-color: var(--border); }td { border-color: rgb(32, 40, 56); }tbody tr:hover { background: rgb(21, 28, 40); }.notice { background: rgb(16, 24, 39); border-color: rgb(39, 59, 97); color: rgb(199, 210, 231); }.detail-list > div { border-color: var(--border); }.status-normal { color: rgb(74, 222, 128); }.badge.low { color: rgb(74, 222, 128); border-color: rgb(35, 98, 61); background: rgb(16, 39, 27); }.badge.medium { color: rgb(251, 191, 36); border-color: rgb(105, 83, 27); background: rgb(42, 34, 13); }.badge.high, .badge.critical { color: rgb(248, 113, 113); border-color: rgb(109, 45, 49); background: rgb(43, 19, 22); }.badge.pending { color: rgb(96, 165, 250); border-color: rgb(39, 78, 136); background: rgb(16, 29, 53); }.module-toolbar { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin-bottom: 16px; }.module-toolbar .search { min-width: 260px; flex: 1 1 0%; }.search, .field input, .field select, .field textarea { background: rgb(13, 18, 27); border: 1px solid var(--border); color: var(--text); border-radius: 7px; padding: 10px 12px; outline: none; }.search:focus, .field input:focus, .field select:focus, .field textarea:focus { border-color: rgb(59, 130, 246); box