lor: var(--muted); font-size: 10px; margin-bottom: 7px; }.summary-item strong { font-size: 20px; }.pagination { display: flex; justify-content: space-between; align-items: center; margin-top: 14px; color: var(--muted); font-size: 11px; }@media (max-width: 700px) {
