}.doctor-name-link { appearance: none; background: none; border: 0px; color: rgb(245, 247, 251); text-align: left; padding: 0px; cursor: pointer; font: inherit; }.doctor-name-link strong { display: block; color: rgb(139, 180, 255); text-decoration: underline; text-underline-offset: 3px; }.doctor-name-link span { display: block; color: var(--muted); font-size: 10px; margin-top: 4px; }.doctor-name-link:hover strong { color: rgb(191, 219, 254); }.doctor-profile-view { display: none; }.doctor-profile-view.active { display: block; }.profile-top-actions { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }.doctor-hero { display: grid; grid-template-columns: auto 1fr auto; gap: 20px; align-items: center; background: linear-gradient(135deg, rgb(17, 22, 32), rgb(12, 20, 35)); border-top-color: ; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-left: 4px solid rgb(37, 99, 235); border-radius: 12px; padding: 24px; margin-bottom: 16px; }.doctor-avatar { width: 72px; height: 72px; border-radius: 50%; display: grid; place-items: center; background: rgb(29, 78, 216); color: rgb(255, 255, 255); font-weight: 800; font-size: 24px; }.doctor-identity h2 { margin: 5px 0px 6px; font-size: 25px; }.doctor-identity p { margin: 0px; color: rgb(184, 194, 209); }.identity-meta { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 13px; }.identity-meta span { font-size: 10px; padding: 6px 9px; border: 1px solid var(--border); border-radius: 999px; color: rgb(201, 210, 223); background: rgb(11, 17, 27); }.profile-risk { text-align: right; min-width: 130px; }.profile-risk > span:first-child { display: block; color: var(--muted); font-size: 10px; }.profile-risk strong { display: block; font-size: 32px; margin: 5px 0